export const getOpenKeysFromMenuData = menuData => {
  return (menuData || []).reduce((pre, item) => {
    // 如果是 flatMenu，跳过自己，只递归 children
    if (item.flatMenu) {
      if (item.children) {
        return pre.concat(getOpenKeysFromMenuData(item.children) || []);
      }
      return pre;
    }
    if (item.key) {
      pre.push(item.key);
    }
    if (item.children) {
      const newArray = pre.concat(getOpenKeysFromMenuData(item.children) || []);
      return newArray;
    }
    return pre;
  }, []);
};
const themeConfig = {
  techBlue: '#1677FF',
  daybreak: '#1890ff',
  dust: '#F5222D',
  volcano: '#FA541C',
  sunset: '#FAAD14',
  cyan: '#13C2C2',
  green: '#52C41A',
  geekblue: '#2F54EB',
  purple: '#722ED1'
};
/**
 * Daybreak-> #1890ff
 *
 * @param val
 */
export function genStringToTheme(val) {
  return val && themeConfig[val] ? themeConfig[val] : val || '';
}
export function clearMenuItem(menusData) {
  return menusData.map(item => {
    const children = item.children || [];
    const finalItem = {
      ...item
    };
    if (!finalItem.name || finalItem.hideInMenu) {
      return null;
    }
    if (finalItem && finalItem?.children) {
      if (!finalItem.hideChildrenInMenu && children.some(child => child && child.name && !child.hideInMenu)) {
        return {
          ...item,
          children: clearMenuItem(children)
        };
      }
      // children 为空就直接删掉
      delete finalItem.children;
    }
    return finalItem;
  }).filter(item => item);
}